import os
import boto3

class MessageAuditStore:
    def __init__(self):
        self.dynamodb = boto3.resource(
            'dynamodb',
            region_name=os.environ.get('AWS_REGION', 'us-east-1') # Default to us-east-1 if not set
        )
        self.table_name = os.environ.get('DYNAMODB_AUDIT_TABLE', 'MessageAuditTable')
        self.table = self.dynamodb.Table(self.table_name)

    def save_message_record(self, message_id: str, timestamp: str, content: str, status: str):
        """
        Persists a processed message record to DynamoDB.
        """
        try:
            self.table.put_item(
                Item={
                    'message_id': message_id,
                    'timestamp': timestamp,
                    'content': content,
                    'status': status
                }
            )
            print(f"Message record {message_id} saved successfully to DynamoDB table {self.table_name}")
        except Exception as e:
            print(f"Error saving message record {message_id} to DynamoDB: {e}")

import google.generativeai as genai
import os

def check_message_safety(text: str) -> dict:
    """
    Checks the given text for unsafe content using Google's Generative AI safety features.

    Args:
        text: The message payload text to check.

    Returns:
        A dictionary containing safety feedback.
    """
    try:
        # Configure the generative AI model with your API key
        # It's recommended to set the API key as an environment variable (e.g., GOOGLE_API_KEY)
        genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))

        model = genai.GenerativeModel('gemini-pro')

        # The generate_content method automatically applies safety filters.
        # If the content is flagged as unsafe, an exception might be raised or
        # the response will contain safety ratings.
        response = model.generate_content(text, safety_settings={
            # You can customize safety settings here if needed,
            # for example, to block certain categories more aggressively.
            # However, default settings are often a good starting point.
            # For demonstration, we'll rely on default blocking behavior.
        })

        # If the response is blocked due to safety, response.prompt_feedback will contain details
        if response.prompt_feedback and response.prompt_feedback.block_reason:
            return {
                "is_safe": False,
                "block_reason": response.prompt_feedback.block_reason.name,
                "safety_ratings": [
                    {"category": rating.category.name, "probability": rating.probability.name}
                    for rating in response.prompt_feedback.safety_ratings
                ]
            }
        else:
            # If no block reason, the content is considered safe under the current settings.
            # We can still return the safety ratings for transparency.
            # Note: For content that doesn't trigger a block, safety_ratings might be empty
            # or indicate very low probability for all categories.
            safety_ratings = []
            if hasattr(response, 'candidates') and response.candidates:
                for candidate in response.candidates:
                    if candidate.safety_ratings:
                        for rating in candidate.safety_ratings:
                            safety_ratings.append({"category": rating.category.name, "probability": rating.probability.name})
            if not safety_ratings and response.prompt_feedback and response.prompt_feedback.safety_ratings:
                safety_ratings = [
                    {"category": rating.category.name, "probability": rating.probability.name}
                    for rating in response.prompt_feedback.safety_ratings
                ]


            return {
                "is_safe": True,
                "safety_ratings": safety_ratings
            }

    except Exception as e:
        return {
            "is_safe": False,
            "error": str(e)
        }

import json
from dataclasses import dataclass, field
from typing import Dict, Any, Optional

@dataclass
class PubSubMessage:
    data: Optional[bytes] = None
    attributes: Dict[str, str] = field(default_factory=dict)
    message_id: Optional[str] = None
    publish_time: Optional[str] = None

    def to_json(self) -> str:
        payload = {}
        if self.data:
            payload['data'] = self.data.decode('utf-8')
        if self.attributes:
            payload['attributes'] = self.attributes
        if self.message_id:
            payload['messageId'] = self.message_id
        if self.publish_time:
            payload['publishTime'] = self.publish_time
        return json.dumps(payload)

    @classmethod
    def from_json(cls, json_str: str) -> 'PubSubMessage':
        payload = json.loads(json_str)
        data = payload.get('data')
        attributes = payload.get('attributes', {})
        message_id = payload.get('messageId')
        publish_time = payload.get('publishTime')
        return cls(
            data=data.encode('utf-8') if data else None,
            attributes=attributes,
            message_id=message_id,
            publish_time=publish_time
        )

def serialize_message(data: Dict[str, Any], attributes: Optional[Dict[str, str]] = None) -> PubSubMessage:
    """Serializes a dictionary into a PubSubMessage."""
    json_data = json.dumps(data).encode('utf-8')
    return PubSubMessage(data=json_data, attributes=attributes or {})

def deserialize_message(message: PubSubMessage) -> Dict[str, Any]:
    """Deserializes a PubSubMessage data into a dictionary."""
    if message.data:
        return json.loads(message.data.decode('utf-8'))
    return {}

from google.cloud import pubsub_v1
import os

class MessagingClient:
    def __init__(self, project_id=None):
        self.project_id = project_id if project_id else os.getenv("GOOGLE_CLOUD_PROJECT")
        if not self.project_id:
            raise ValueError("Google Cloud Project ID not provided and GOOGLE_CLOUD_PROJECT environment variable not set.")
        self.publisher = pubsub_v1.PublisherClient()
        self.subscriber = pubsub_v1.SubscriberClient()

    def publish_message(self, topic_id, message_data):
        topic_path = self.publisher.topic_path(self.project_id, topic_id)
        message_bytes = message_data.encode("utf-8")
        try:
            publish_future = self.publisher.publish(topic_path, message_bytes)
            publish_future.result()  # Verify the publication succeeded
            return f"Published message to {topic_path}"
        except Exception as e:
            return f"Failed to publish message: {e}"

    def subscribe_to_topic(self, subscription_id, callback):
        subscription_path = self.subscriber.subscription_path(self.project_id, subscription_id)

        streaming_pull_future = self.subscriber.subscribe(subscription_path, callback=callback)
        print(f"Listening for messages on {subscription_path}")

        # The subscriber is non-blocking, so we must keep the main thread from
        # exiting to allow it to process messages in the background.
        try:
            streaming_pull_future.result()
        except TimeoutError:
            streaming_pull_future.cancel()
            streaming_pull_future.result()

    def create_topic(self, topic_id):
        topic_path = self.publisher.topic_path(self.project_id, topic_id)
        try:
            topic = self.publisher.create_topic(request={"name": topic_path})
            return f"Topic {topic.name} created."
        except Exception as e:
            return f"Failed to create topic: {e}"

    def create_subscription(self, topic_id, subscription_id):
        topic_path = self.publisher.topic_path(self.project_id, topic_id)
        subscription_path = self.subscriber.subscription_path(self.project_id, subscription_id)
        try:
            subscription = self.subscriber.create_subscription(
                request={"name": subscription_path, "topic": topic_path}
            )
            return f"Subscription {subscription.name} created on topic {topic_id}."
        except Exception as e:
            return f"Failed to create subscription: {e}"

    def delete_topic(self, topic_id):
        topic_path = self.publisher.topic_path(self.project_id, topic_id)
        try:
            self.publisher.delete_topic(request={"topic": topic_path})
            return f"Topic {topic_id} deleted."
        except Exception as e:
            return f"Failed to delete topic: {e}"

    def delete_subscription(self, subscription_id):
        subscription_path = self.subscriber.subscription_path(self.project_id, subscription_id)
        try:
            self.subscriber.delete_subscription(request={"subscription": subscription_path})
            return f"Subscription {subscription_id} deleted."
        except Exception as e:
            return f"Failed to delete subscription: {e}"

from google.cloud import pubsub_v1
import os

# Set your Google Cloud Project ID and Subscription Name
# You can set these as environment variables or replace them directly
project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
subscription_id = os.environ.get("GOOGLE_CLOUD_SUBSCRIPTION_ID")

if not project_id or not subscription_id:
    print("Please set the GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_SUBSCRIPTION_ID environment variables or hardcode them in the script.")
    exit(1)

subscriber = pubsub_v1.SubscriberClient()
subscription_path = subscriber.subscription_path(project_id, subscription_id)

def consume_message():
    print(f"Listening for messages on {subscription_path}...")

    # The `sub_client.subscribe` method is asynchronous, so we will use a Future to block until a message is received.
    # We are pulling only one message at a time to fulfill the task requirement of "consumes one message".
    response = subscriber.pull(
        request={"subscription": subscription_path, "max_messages": 1, "return_immediately": True}
    )

    if response.received_messages:
        for received_message in response.received_messages:
            message_data = received_message.message.data.decode("utf-8")
            print(f"Received message: {message_data}")
            # Acknowledge the message to remove it from the subscription
            subscriber.acknowledge(
                request={"subscription": subscription_path, "ack_ids": [received_message.ack_id]}
            )
            print(f"Acknowledged message: {received_message.ack_id}")
    else:
        print("No messages received.")

    subscriber.close()

if __name__ == "__main__":
    consume_message()
